export interface CalendarShift { key:string; start:string; end:string; break_minutes:number; remote_allowed:boolean }
export interface CalendarSchedule { weekdays:Array<{weekday:number;shifts:CalendarShift[]}>; holidays:string[]; overtime:{enabled:boolean;requires_approval:boolean;basis:string} }
export interface LeaveRule { key:string; title_en:string; title_vi:string; paid:boolean; annual_grant_minutes:number; monthly_accrual_minutes:number; prorate_on_start:boolean; carryover_limit_minutes:number; max_negative_minutes:number; evidence_required:boolean; exclude_holidays:boolean; basis:string }
export interface WorkCalendar {id:string;calendar_key:string;version_number:number;title_en:string;title_vi:string;legal_entity:string;timezone:string;schedule_json:string;state:string;created_by:string;created_at:string;reviewed_by:string|null;reviewed_at:string|null;review_reason:string|null;activated_by:string|null;activated_at:string|null;version:number;actor_id:string;updated_at:string}
export interface WorkAssignment {id:string;person_id:string;employment_id:string;calendar_version_id:string;effective_from:string;effective_to:string|null;version:number;assigned_by:string;assigned_at:string;actor_id:string;created_at:string;updated_at:string;employee_code?:string;name?:string;preferred_name?:string;started_on?:string|null;ended_on?:string|null}
export interface TimePeriod {id:string;period_key:string;starts_on:string;ends_on:string;state:string;snapshot_json:string|null;snapshot_checksum:string|null;entry_count:number|null;opened_by:string;opened_at:string;locked_by:string|null;locked_at:string|null;reopened_by:string|null;reopened_at:string|null;reopen_reason:string|null;version:number;actor_id:string;created_at:string;updated_at:string}
