export interface TimeAdjustment {id:string;entry_id:string;expected_entry_version:number;old_check_in_utc:string;old_check_out_utc:string;old_break_minutes:number;proposed_check_in_utc:string;proposed_check_out_utc:string;proposed_break_minutes:number;proposed_worked_minutes:number;reason:string;state:string;submitted_by:string;submitted_at:string;reviewed_by:string|null;reviewed_at:string|null;review_reason:string|null;version:number;actor_id:string;created_at:string;updated_at:string;timezone?:string}
export interface LeavePolicy {id:string;policy_key:string;version_number:number;title_en:string;title_vi:string;rules_json:string;state:string;created_by:string;created_at:string;reviewed_by:string|null;reviewed_at:string|null;review_reason:string|null;activated_by:string|null;activated_at:string|null;version:number;actor_id:string;updated_at:string}
export interface LeaveAssignment {id:string;person_id:string;employment_id:string;policy_version_id:string;effective_from:string;effective_to:string|null;assigned_by:string;assigned_at:string;version:number;actor_id:string;created_at:string;updated_at:string;employee_code?:string;preferred_name?:string;calendar_version_id?:string}
export interface LeaveRequest {id:string;person_id:string;employment_id:string;assignment_id:string;policy_version_id:string;leave_type_key:string;starts_on:string;ends_on:string;portion:string;requested_minutes:number;calculation_json:string;private_reason:string;cancellation_reason:string|null;handoff_note:string;state:string;submitted_by:string;submitted_at:string;reviewed_by:string|null;reviewed_at:string|null;review_reason:string|null;version:number;actor_id:string;created_at:string;updated_at:string;employee_code?:string;preferred_name?:string;leave_title_en?:string;leave_title_vi?:string;paid?:number}
export interface LeaveLedger {id:string;person_id:string;employment_id:string;assignment_id:string;policy_version_id:string;leave_type_key:string;event_kind:string;minutes:number;period_key:string;reference_id:string;reason:string;actor_id:string;created_at:string}

const validDate=(value:string)=>/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value+"T00:00:00Z"))&&new Date(value+"T00:00:00Z").toISOString().slice(0,10)===value;
const strictUtc=(value:string)=>/^\d{4}-\d\d-\d\dT\d\d:\d\d(?::\d\d(?:\.\d{1,3})?)?Z$/.test(value)&&Number.isFinite(Date.parse(value));
const timeText=(value:string)=>/^([01]\d|2[0-3]):[0-5]\d$/.test(value);
const weekday=(date:string)=>{const day=new Date(date+"T00:00:00Z").getUTCDay();return day===0?7:day};
export const dayMinutes=(shift:CalendarShift)=>{const [sh,sm]=shift.start.split(":").map(Number),[eh,em]=shift.end.split(":").map(Number);let minutes=eh*60+em-(sh*60+sm);if(minutes<=0)minutes+=1440;return minutes-shift.break_minutes};
const dateRange=(from:string,to:string,max=370):string[]=>{if(!validDate(from)||!validDate(to)||to<from)throw new HrmError("invalid_date");const count=Math.round((Date.parse(to+"T00:00:00Z")-Date.parse(from+"T00:00:00Z"))/86400000)+1;if(count>max)throw new HrmError("date_range_too_large",400);return Array.from({length:count},(_,i)=>new Date(Date.parse(from+"T00:00:00Z")+i*86400000).toISOString().slice(0,10));};
const allowedCalendarKey=(key:string)=>/^[a-z0-9][a-z0-9_-]{1,79}$/.test(key);
function fail(error:string,status=409):never{throw new HrmError(error,status)}
function live(user:WorkspaceUser){if(user.hrmEnabled!==true)fail("hrm_closed",503)}

export function parseCalendarSchedule(raw:string):CalendarSchedule{
 let data:unknown;try{data=JSON.parse(raw)}catch{fail("calendar_invalid")}
 if(!data||typeof data!=="object")fail("calendar_invalid");const value=data as Record<string,unknown>;
 if(!Array.isArray(value.weekdays)||value.weekdays.length!==7||!Array.isArray(value.holidays)||!value.overtime||typeof value.overtime!=="object")fail("calendar_invalid");
 const weekdayRows=value.weekdays as unknown[],seenDays=new Set<number>(),shifts:CalendarShift[]=[];
 for(const row of weekdayRows){if(!row||typeof row!=="object")fail("calendar_invalid");const day=row as Record<string,unknown>;if(!Number.isInteger(day.weekday)||Number(day.weekday)<1||Number(day.weekday)>7||seenDays.has(Number(day.weekday))||!Array.isArray(day.shifts))fail("calendar_invalid");seenDays.add(Number(day.weekday));const seenKeys=new Set<string>();
  for(const item of day.shifts){if(!item||typeof item!=="object")fail("calendar_invalid");const shift=item as Record<string,unknown>;if(typeof shift.key!=="string"||!/^[A-Za-z0-9_-]{1,40}$/.test(shift.key)||seenKeys.has(shift.key)||typeof shift.start!=="string"||!timeText(shift.start)||typeof shift.end!=="string"||!timeText(shift.end)||!Number.isInteger(shift.break_minutes)||Number(shift.break_minutes)<0||typeof shift.remote_allowed!=="boolean")fail("calendar_invalid");const normalized={key:shift.key,start:shift.start,end:shift.end,break_minutes:Number(shift.break_minutes),remote_allowed:shift.remote_allowed};if(dayMinutes(normalized)<=0)fail("calendar_invalid");seenKeys.add(shift.key);shifts.push(normalized);}
 }
 if(seenDays.size!==7)fail("calendar_invalid");const holidays=(value.holidays as unknown[]).map(date=>{if(typeof date!=="string"||!validDate(date))fail("calendar_invalid");return date});if(new Set(holidays).size!==holidays.length)fail("calendar_invalid");
 const overtime=value.overtime as Record<string,unknown>;if(typeof overtime.enabled!=="boolean"||typeof overtime.requires_approval!=="boolean"||typeof overtime.basis!=="string"||!overtime.basis.trim()||overtime.basis.length>1000)fail("calendar_invalid");
 return {weekdays:(weekdayRows as Array<Record<string,unknown>>).map(day=>({weekday:Number(day.weekday),shifts:(day.shifts as Array<Record<string,unknown>>).map(shift=>({key:String(shift.key),start:String(shift.start),end:String(shift.end),break_minutes:Number(shift.break_minutes),remote_allowed:Boolean(shift.remote_allowed)}))})),holidays,overtime:{enabled:overtime.enabled,requires_approval:overtime.requires_approval,basis:overtime.basis.trim()}};
}
export function parseLeaveRules(raw:string):LeaveRule[]{
 let data:unknown;try{data=JSON.parse(raw)}catch{fail("leave_policy_invalid")}
 if(!Array.isArray(data)||data.length<1||data.length>50)fail("leave_policy_invalid");const rows=data as unknown[],result:LeaveRule[]=[];
 for(const item of rows){if(!item||typeof item!=="object")fail("leave_policy_invalid");const row=item as Record<string,unknown>;
  if(typeof row.key!=="string"||!/^[a-z0-9][a-z0-9_-]{0,39}$/.test(row.key)||typeof row.title_en!=="string"||!row.title_en.trim()||typeof row.title_vi!=="string"||!row.title_vi.trim()||typeof row.paid!=="boolean"||typeof row.prorate_on_start!=="boolean"||typeof row.evidence_required!=="boolean"||typeof row.exclude_holidays!=="boolean"||typeof row.basis!=="string"||!row.basis.trim()||row.basis.length>1000)fail("leave_policy_invalid");
  for(const key of ["annual_grant_minutes","monthly_accrual_minutes","carryover_limit_minutes","max_negative_minutes"])if(!Number.isInteger(row[key])||Number(row[key])<0||Number(row[key])>1000000)fail("leave_policy_invalid");
  result.push({key:row.key,title_en:row.title_en.trim(),title_vi:row.title_vi.trim(),paid:row.paid,annual_grant_minutes:Number(row.annual_grant_minutes),monthly_accrual_minutes:Number(row.monthly_accrual_minutes),prorate_on_start:row.prorate_on_start,carryover_limit_minutes:Number(row.carryover_limit_minutes),max_negative_minutes:Number(row.max_negative_minutes),evidence_required:row.evidence_required,exclude_holidays:row.exclude_holidays,basis:row.basis.trim()});
 }
 if(new Set(result.map(row=>row.key)).size!==result.length)fail("leave_policy_invalid");return result;
}
export function activeShift(schedule:CalendarSchedule,date:string,key:string){if(schedule.holidays.includes(date))return null;const rows=schedule.weekdays.find(row=>row.weekday===weekday(date));return rows?.shifts.find(shift=>shift.key===key)??null}
export function actualMinutes(start:string,end:string,breakMinutes:number){if(!strictUtc(start)||!strictUtc(end)||Date.parse(end)<=Date.parse(start))fail("time_interval_invalid");const gross=Math.round((Date.parse(end)-Date.parse(start))/60000);if(gross>1440||!Number.isInteger(breakMinutes)||breakMinutes<0||breakMinutes>=gross)fail("time_interval_invalid");return gross-breakMinutes}
export function localParts(instant:string,timezone:string){const formatted=new Intl.DateTimeFormat("en-CA",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date(instant));const parts=Object.fromEntries(formatted.map(part=>[part.type,part.value]));return {date:`${parts.year}-${parts.month}-${parts.day}`,time:`${parts.hour}:${parts.minute}`}}
export function nextDate(date:string){return new Date(Date.parse(date+"T00:00:00Z")+86400000).toISOString().slice(0,10)}
function year(date:string){return date.slice(0,4)}
function monthKey(date:string){return date.slice(0,7)}
function checkTimeRange(value:string){if(!validDate(value))fail("invalid_date",400)}

async function reviewerScope(db:D1Database,user:WorkspaceUser,personId:string,kind:"time"|"leave"):Promise<void>{
 const allowed=kind==="time"?user.can("hrm.time.manage"):user.can("hrm.leave.manage");if(allowed||user.admin)return;
 const review=kind==="time"?user.can("hrm.time.review"):user.can("hrm.leave.review");if(!review)fail("forbidden",403);
 const person=await db.prepare("SELECT e.manager_user_id FROM hrm_people p JOIN hrm_employments e ON e.person_id=p.id AND e.id=(SELECT e2.id FROM hrm_employments e2 WHERE e2.person_id=p.id ORDER BY CASE WHEN e2.status!='ended' THEN 0 ELSE 1 END,e2.started_on DESC LIMIT 1) WHERE p.id=? AND e.status!='ended'").bind(personId).first<{manager_user_id:string|null}>();
 if(!person||person.manager_user_id!==user.id)fail("not_found",404);
}
async function ownPerson(db:D1Database,user:WorkspaceUser,personId?:string):Promise<Person>{const person=await personFor(db,user,personId);if(!own(person,user))fail("not_found",404);return person}
async function activeAssignment(db:D1Database,person:Person,date:string):Promise<WorkAssignment&{timezone:string;schedule_json:string}>{return await db.prepare(`SELECT a.*,c.timezone,c.schedule_json FROM hrm_work_assignments a JOIN hrm_work_calendar_versions c ON c.id=a.calendar_version_id JOIN hrm_employments e ON e.id=a.employment_id WHERE a.person_id=? AND a.employment_id=? AND a.effective_from<=? AND (a.effective_to IS NULL OR a.effective_to>=?) AND e.status!='ended' AND (e.started_on IS NULL OR e.started_on<=?) AND (e.ended_on IS NULL OR e.ended_on>=?) ORDER BY a.effective_from DESC LIMIT 1`).bind(person.id,person.employment_id,date,date,date,date).first<WorkAssignment&{timezone:string;schedule_json:string}>()??fail("calendar_assignment_missing",409)}
function timezoneValid(timezone:string){try{new Intl.DateTimeFormat("en-US",{timeZone:timezone}).format(new Date());return true}catch{return false}}

export async function listCalendarVersions(db:D1Database,user:WorkspaceUser):Promise<WorkCalendar[]>{if(!user.can("hrm.time.manage")&&!user.can("hrm.time.configure")&&!user.can("hrm.time.review"))fail("forbidden",403);return (await db.prepare("SELECT * FROM hrm_work_calendar_versions ORDER BY calendar_key,version_number DESC LIMIT 100").all<WorkCalendar>()).results}
export async function createCalendarVersion(db:D1Database,user:WorkspaceUser,key:string,input:{calendar_key:string;title_en:string;title_vi:string;legal_entity:string;timezone:string;schedule_json:string}):Promise<string>{requirePermission(user,"hrm.time.configure");if(!allowedCalendarKey(input.calendar_key)||!input.title_en.trim()||!input.title_vi.trim()||!input.legal_entity.trim()||!timezoneValid(input.timezone))fail("calendar_invalid");const schedule=parseCalendarSchedule(input.schedule_json);const existing=await db.prepare("SELECT COALESCE(MAX(version_number),0) AS n FROM hrm_work_calendar_versions WHERE calendar_key=?").bind(input.calendar_key).first<{n:number}>(),versionNumber=(existing?.n??0)+1,target=id("calendar"),time=now(),payload={...input,schedule};await command(db,user,key,"work_calendar_create",payload,target,[guard(db,"NOT EXISTS(SELECT 1 FROM hrm_work_calendar_versions WHERE calendar_key=? AND version_number=?)",[input.calendar_key,versionNumber])],[db.prepare("INSERT INTO hrm_work_calendar_versions(id,calendar_key,version_number,title_en,title_vi,legal_entity,timezone,schedule_json,state,created_by,created_at,version,actor_id,updated_at) VALUES(?,?,?,?,?,?,?,?,'draft',?,?,1,?,?)").bind(target,input.calendar_key,versionNumber,input.title_en.trim(),input.title_vi.trim(),input.legal_entity.trim(),input.timezone,JSON.stringify(schedule),user.id,time,user.id,time),db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'work_calendar_created',NULL,?,?,?)").bind(user.id,target,JSON.stringify({calendar_key:input.calendar_key,version:versionNumber}),time),db.prepare("DELETE FROM hrm_write_guards")]);return target}
export async function reviewCalendarVersion(db:D1Database,user:WorkspaceUser,key:string,calendarId:string,version:number,approve:boolean,reason:string):Promise<void>{requirePermission(user,"hrm.time.review");if(!reason.trim())fail("reason_required",400);const row=await db.prepare("SELECT id,created_by,state FROM hrm_work_calendar_versions WHERE id=?").bind(calendarId).first<{id:string;created_by:string;state:string}>();if(!row)fail("not_found",404);if(row.created_by===user.id)fail("self_approval",403);const state=approve?"reviewed":"rejected",payload={calendarId,version,approve,reason:reason.trim()},time=now();await command(db,user,key,"work_calendar_review",payload,calendarId,[guard(db,"EXISTS(SELECT 1 FROM hrm_work_calendar_versions WHERE id=? AND version=? AND state='draft' AND created_by!=?)",[calendarId,version,user.id])],[db.prepare("UPDATE hrm_work_calendar_versions SET state=?,reviewed_by=?,reviewed_at=?,review_reason=?,version=version+1,actor_id=?,updated_at=? WHERE id=? AND version=? AND state='draft'").bind(state,user.id,time,reason.trim(),user.id,time,calendarId,version),db.prepare("DELETE FROM hrm_write_guards")])}
export async function activateCalendarVersion(db:D1Database,user:WorkspaceUser,key:string,calendarId:string,version:number):Promise<void>{requirePermission(user,"hrm.time.configure");const row=await db.prepare("SELECT * FROM hrm_work_calendar_versions WHERE id=?").bind(calendarId).first<WorkCalendar>();if(!row)fail("not_found",404);if(row.state!=="reviewed"||!row.reviewed_by||row.created_by===user.id)fail("calendar_review_required",403);const payload={calendarId,version},time=now(),active=await db.prepare("SELECT id FROM hrm_work_calendar_versions WHERE calendar_key=? AND state='active'").bind(row.calendar_key).first<{id:string}>(),writes:D1PreparedStatement[]=[];if(active)writes.push(db.prepare("UPDATE hrm_work_calendar_versions SET state='retired',version=version+1,actor_id=?,updated_at=? WHERE id=? AND state='active'").bind(user.id,time,active.id));writes.push(db.prepare("UPDATE hrm_work_calendar_versions SET state='active',activated_by=?,activated_at=?,version=version+1,actor_id=?,updated_at=? WHERE id=? AND version=? AND state='reviewed'").bind(user.id,time,user.id,time,calendarId,version),db.prepare("DELETE FROM hrm_write_guards"));await command(db,user,key,"work_calendar_activate",payload,calendarId,[guard(db,"EXISTS(SELECT 1 FROM hrm_work_calendar_versions WHERE id=? AND version=? AND state='reviewed' AND reviewed_by!=?)",[calendarId,version,user.id])],writes)}

export async function assignWorkCalendar(db:D1Database,user:WorkspaceUser,key:string,personId:string,calendarVersionId:string,effectiveFrom:string):Promise<string>{requirePermission(user,"hrm.time.manage");live(user);checkTimeRange(effectiveFrom);const person=await personFor(db,user,personId);if(person.started_on&&effectiveFrom<person.started_on||person.ended_on&&effectiveFrom>person.ended_on)fail("invalid_date",400);const calendar=await db.prepare("SELECT id,state FROM hrm_work_calendar_versions WHERE id=?").bind(calendarVersionId).first<{id:string;state:string}>();if(!calendar||calendar.state!=="active")fail("calendar_not_active",409);const assignmentId=id("work_assignment"),time=now(),payload={personId,employmentId:person.employment_id,calendarVersionId,effectiveFrom};await command(db,user,key,"work_calendar_assign",payload,assignmentId,[guard(db,"EXISTS(SELECT 1 FROM hrm_employments WHERE id=? AND person_id=? AND version=? AND status!='ended')",[person.employment_id,person.id,person.version]),guard(db,"NOT EXISTS(SELECT 1 FROM hrm_work_assignments WHERE employment_id=? AND effective_to IS NULL AND effective_from>=?)",[person.employment_id,effectiveFrom]),guard(db,"NOT EXISTS(SELECT 1 FROM hrm_work_assignments WHERE employment_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?))",[person.employment_id,effectiveFrom,effectiveFrom]),guard(db,"EXISTS(SELECT 1 FROM hrm_work_calendar_versions WHERE id=? AND state='active')",[calendarVersionId])],[db.prepare("INSERT INTO hrm_work_assignments(id,person_id,employment_id,calendar_version_id,effective_from,assigned_by,assigned_at,version,actor_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,?,?,?)").bind(assignmentId,person.id,person.employment_id,calendarVersionId,effectiveFrom,user.id,time,user.id,time,time),db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'work_calendar_assigned',?,?,?,?)").bind(user.id,person.id,assignmentId,JSON.stringify({calendar_version_id:calendarVersionId,effective_from:effectiveFrom}),time),db.prepare("DELETE FROM hrm_write_guards")]);return assignmentId}
export async function endWorkAssignment(db:D1Database,user:WorkspaceUser,key:string,assignmentId:string,version:number,effectiveTo:string,reason:string):Promise<void>{requirePermission(user,"hrm.time.manage");checkTimeRange(effectiveTo);if(!reason.trim())fail("reason_required",400);const row=await db.prepare("SELECT * FROM hrm_work_assignments WHERE id=?").bind(assignmentId).first<WorkAssignment>();if(!row)fail("not_found",404);if(effectiveTo<row.effective_from)fail("invalid_date",400);const time=now(),payload={assignmentId,version,effectiveTo,reason:reason.trim()};await command(db,user,key,"work_calendar_end",payload,assignmentId,[guard(db,"EXISTS(SELECT 1 FROM hrm_work_assignments WHERE id=? AND version=? AND (effective_to IS NULL OR effective_to>=?))",[assignmentId,version,effectiveTo])],[db.prepare("UPDATE hrm_work_assignments SET effective_to=?,version=version+1,actor_id=?,updated_at=? WHERE id=? AND version=?").bind(effectiveTo,user.id,time,assignmentId,version),db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'work_calendar_ended',?,?,?,?)").bind(user.id,row.person_id,assignmentId,JSON.stringify({effective_to:effectiveTo,reason:reason.trim()}),time),db.prepare("DELETE FROM hrm_write_guards")])}

export async function listWorkAssignments(db:D1Database,user:WorkspaceUser):Promise<WorkAssignment[]>{live(user);if(!user.can("hrm.time.manage")&&!user.can("hrm.time.review"))fail("forbidden",403);const team=!user.can("hrm.time.manage");return (await db.prepare(`SELECT a.*,p.employee_code,p.preferred_name FROM hrm_work_assignments a JOIN hrm_people p ON p.id=a.person_id ${team?"JOIN hrm_employments e ON e.id=a.employment_id AND e.manager_user_id=?":""} ORDER BY a.effective_from DESC LIMIT 500`).bind(...(team?[user.id]:[])).all<WorkAssignment>()).results}

export async function createTimePeriod(db:D1Database,user:WorkspaceUser,key:string,input:{period_key:string;starts_on:string;ends_on:string}):Promise<string>{requirePermission(user,"hrm.time.manage");live(user);checkTimeRange(input.starts_on);checkTimeRange(input.ends_on);if(input.ends_on<input.starts_on||!input.period_key.trim()||input.period_key.length>30)fail("invalid_date",400);const target=id("time_period"),time=now(),payload=input;await command(db,user,key,"time_period_create",payload,target,[guard(db,"NOT EXISTS(SELECT 1 FROM hrm_time_periods WHERE period_key=?)",[input.period_key]),guard(db,"NOT EXISTS(SELECT 1 FROM hrm_time_periods WHERE state IN ('open','reviewing','locked','reopen_requested','reopened') AND starts_on<=? AND ends_on>=?)",[input.ends_on,input.starts_on])],[db.prepare("INSERT INTO hrm_time_periods(id,period_key,starts_on,ends_on,state,opened_by,opened_at,version,actor_id,created_at,updated_at) VALUES(?,?,?,?,'open',?,?,1,?,?,?)").bind(target,input.period_key.trim(),input.starts_on,input.ends_on,user.id,time,user.id,time,time),db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'time_period_opened',NULL,?,?,?)").bind(user.id,target,JSON.stringify(input),time),db.prepare("DELETE FROM hrm_write_guards")]);return target}
