export async function assignLeavePolicy(db:D1Database,user:WorkspaceUser,key:string,personId:string,policyId:string,effectiveFrom:string):Promise<string>{requirePermission(user,"hrm.leave.manage");live(user);checkTimeRange(effectiveFrom);const person=await personFor(db,user,personId);if(person.started_on&&effectiveFrom<person.started_on||person.ended_on&&effectiveFrom>person.ended_on)fail("invalid_date",400);const policy=await db.prepare("SELECT * FROM hrm_leave_policy_versions WHERE id=? AND state='active'").bind(policyId).first<LeavePolicy>();if(!policy)fail("leave_policy_not_active",409);const rules=parseLeaveRules(policy.rules_json),assignmentId=id("leave_assignment"),time=now(),period=year(effectiveFrom),ledger:D1PreparedStatement[]=[];for(const rule of rules){if(rule.annual_grant_minutes===0)continue;const grant=rule.prorate_on_start?Math.floor(rule.annual_grant_minutes*(12-Number(effectiveFrom.slice(5,7))+1)/12):rule.annual_grant_minutes;if(grant>0)ledger.push(db.prepare("INSERT INTO hrm_leave_ledger(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,event_kind,minutes,period_key,reference_id,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,'annual_grant',?,?,?,?,?,?)").bind(id("leave_event"),person.id,person.employment_id,assignmentId,policyId,rule.key,grant,period,`${assignmentId}:${rule.key}:${period}`,"Configured annual grant; prorating follows the reviewed version.",user.id,time))}const payload={personId,employmentId:person.employment_id,policyId,effectiveFrom};await command(db,user,key,"leave_policy_assign",payload,assignmentId,[guard(db,"EXISTS(SELECT 1 FROM hrm_employments WHERE id=? AND person_id=? AND version=? AND status!='ended')",[person.employment_id,person.id,person.version]),guard(db,"NOT EXISTS(SELECT 1 FROM hrm_leave_policy_assignments WHERE employment_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?))",[person.employment_id,effectiveFrom,effectiveFrom]),guard(db,"NOT EXISTS(SELECT 1 FROM hrm_time_periods WHERE state IN ('reviewing','locked','reopen_requested','reopened') AND ends_on>=?)",[effectiveFrom]),guard(db,"EXISTS(SELECT 1 FROM hrm_leave_policy_versions WHERE id=? AND state='active')",[policyId])],[db.prepare("INSERT INTO hrm_leave_policy_assignments(id,person_id,employment_id,policy_version_id,effective_from,assigned_by,assigned_at,version,actor_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,?,?,?)").bind(assignmentId,person.id,person.employment_id,policyId,effectiveFrom,user.id,time,user.id,time,time),...ledger,db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'leave_policy_assigned',?,?,?,?)").bind(user.id,person.id,assignmentId,JSON.stringify({policy_version_id:policyId,effective_from:effectiveFrom,annual_grants:ledger.length}),time),db.prepare("DELETE FROM hrm_write_guards")]);return assignmentId}
