export async function runMonthlyLeaveAccrual(db:D1Database,user:WorkspaceUser,key:string,throughMonth:string):Promise<number>{
 requirePermission(user,"hrm.leave.manage");live(user);
 if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(throughMonth)||throughMonth>=monthKey(localDate()))fail("invalid_date",400);
 const assignments=(await db.prepare("SELECT a.*,p.rules_json FROM hrm_leave_policy_assignments a JOIN hrm_leave_policy_versions p ON p.id=a.policy_version_id WHERE a.effective_from<=?").bind(throughMonth+"-31").all<LeaveAssignment&{rules_json:string}>()).results;
 const writes:D1PreparedStatement[]=[],time=now();let inserted=0;
 for(const assignment of assignments){
  if(assignment.effective_to&&assignment.effective_to<throughMonth+"-01")continue;
  const endMonth=assignment.effective_to&&monthKey(assignment.effective_to)<throughMonth?monthKey(assignment.effective_to):throughMonth;
  for(const rule of parseLeaveRules(assignment.rules_json)){
   if(!rule.monthly_accrual_minutes)continue;
   let cursor=monthKey(assignment.effective_from);
   while(cursor<=endMonth){
    const reference=`${assignment.id}:${rule.key}:${cursor}`;
    if(!await db.prepare("SELECT 1 FROM hrm_leave_ledger WHERE reference_id=? AND event_kind='accrual'").bind(reference).first()){
     writes.push(db.prepare("INSERT INTO hrm_leave_ledger(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,event_kind,minutes,period_key,reference_id,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,'accrual',?,?,?,?,?,?)").bind(id("leave_event"),assignment.person_id,assignment.employment_id,assignment.id,assignment.policy_version_id,rule.key,rule.monthly_accrual_minutes,cursor,reference,"Configured monthly accrual.",user.id,time));inserted++;
    }
    const [y,m]=cursor.split("-").map(Number);cursor=new Date(Date.UTC(y,m,1)).toISOString().slice(0,7);
   }
  }
 }
 if(!writes.length)return 0;
 const payload={throughMonth,assignmentIds:assignments.map(row=>row.id)};
 await command(db,user,key,"leave_accrual_run",payload,id("leave_accrual_run"),[guard(db,"EXISTS(SELECT 1 FROM hrm_settings WHERE id=1)",[])],[...writes,db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'leave_accrual_run',NULL,?,?,?)").bind(user.id,"monthly:"+throughMonth,JSON.stringify({assignment_count:assignments.length,entries:inserted}),time),db.prepare("DELETE FROM hrm_write_guards")]);return inserted;
}

