export async function previewLeaveRequest(db:D1Database,user:WorkspaceUser,input:{personId?:string;startsOn:string;endsOn:string;portion:"full"|"half_first"|"half_second";leaveTypeKey:string}):Promise<{person:Person;assignment:LeaveAssignment&{rules_json:string;timezone:string;schedule_json:string;calendar_version_id:string};rule:LeaveRule;requestedMinutes:number;days:Array<{date:string;minutes:number;holiday:boolean;shiftKeys:string[]}>;balanceMinutes:number}>{live(user);const person=input.personId?await personFor(db,user,input.personId):await ownPerson(db,user);if(!own(person,user)&&!user.can("hrm.leave.manage"))fail("not_found",404);const dates=dateRange(input.startsOn,input.endsOn),assignment=await leaveAssignment(db,person,input.startsOn);if(assignment.effective_to&&assignment.effective_to<input.endsOn)fail("leave_range_crosses_policy",409);const calendarAtEnd=await activeAssignment(db,person,input.endsOn);if(calendarAtEnd.id!==assignment.id&&calendarAtEnd.calendar_version_id!==assignment.calendar_version_id)fail("leave_range_crosses_policy",409);const rules=parseLeaveRules(assignment.rules_json),rule=rules.find(row=>row.key===input.leaveTypeKey);if(!rule)fail("leave_type_unavailable",409);const schedule=parseCalendarSchedule(assignment.schedule_json),days:Array<{date:string;minutes:number;holiday:boolean;shiftKeys:string[]}>=[];for(const date of dates){const holiday=schedule.holidays.includes(date),day=schedule.weekdays.find(row=>row.weekday===weekday(date)),shifts=holiday&&rule.exclude_holidays?[]:day?.shifts??[];days.push({date,minutes:shifts.reduce((sum,shift)=>sum+dayMinutes(shift),0),holiday,shiftKeys:shifts.map(shift=>shift.key)})}if(input.portion!=="full"){const working=days.filter(day=>day.minutes>0);if(working.length!==1)fail("half_day_single_workday",400);working[0].minutes=Math.ceil(working[0].minutes/2)}const requestedMinutes=days.reduce((sum,day)=>sum+day.minutes,0);if(requestedMinutes<=0)fail("leave_no_work_time",409);const balance=await db.prepare("SELECT COALESCE((SELECT SUM(minutes) FROM hrm_leave_ledger WHERE employment_id=? AND leave_type_key=?),0)-COALESCE((SELECT SUM(requested_minutes) FROM hrm_leave_requests WHERE employment_id=? AND leave_type_key=? AND state='pending_approval'),0) AS n").bind(person.employment_id,rule.key,person.employment_id,rule.key).first<{n:number}>();return {person,assignment,rule,requestedMinutes,days,balanceMinutes:balance?.n??0}}
export async function listLeaveBalances(db:D1Database,user:WorkspaceUser,personId?:string):Promise<Array<{leave_type_key:string;balance_minutes:number;pending_minutes:number;available_minutes:number}>>{live(user);const person=personId?await personFor(db,user,personId):await ownPerson(db,user),today=localDate();if(!own(person,user)&&!user.can("hrm.leave.manage")&&!user.can("hrm.leave.review"))fail("not_found",404);const assignment=await db.prepare("SELECT a.id,a.policy_version_id,p.rules_json FROM hrm_leave_policy_assignments a JOIN hrm_leave_policy_versions p ON p.id=a.policy_version_id WHERE a.person_id=? AND a.employment_id=? AND a.effective_from<=? AND (a.effective_to IS NULL OR a.effective_to>=?) ORDER BY a.effective_from DESC LIMIT 1").bind(person.id,person.employment_id,today,today).first<{id:string;policy_version_id:string;rules_json:string}>();if(!assignment)return [];const rules=parseLeaveRules(assignment.rules_json),balances=[];for(const rule of rules){const row=await db.prepare("SELECT COALESCE((SELECT SUM(minutes) FROM hrm_leave_ledger WHERE employment_id=? AND leave_type_key=?),0) AS balance,COALESCE((SELECT SUM(requested_minutes) FROM hrm_leave_requests WHERE employment_id=? AND leave_type_key=? AND state='pending_approval'),0) AS pending").bind(person.employment_id,rule.key,person.employment_id,rule.key).first<{balance:number;pending:number}>();balances.push({leave_type_key:rule.key,balance_minutes:row?.balance??0,pending_minutes:row?.pending??0,available_minutes:(row?.balance??0)-(row?.pending??0)})}return balances}
export async function submitLeaveRequest(db:D1Database,user:WorkspaceUser,key:string,input:{startsOn:string;endsOn:string;portion:"full"|"half_first"|"half_second";leaveTypeKey:string;privateReason:string;handoffNote:string}):Promise<string>{const preview=await previewLeaveRequest(db,user,{...input});if(input.privateReason.length>1000||input.handoffNote.length>500)fail("invalid_request",400);if(preview.rule.evidence_required)fail("leave_evidence_required",409);if(preview.rule.paid&&preview.balanceMinutes<preview.requestedMinutes&&preview.rule.max_negative_minutes<preview.requestedMinutes-preview.balanceMinutes)fail("leave_balance_insufficient",409);const requestId=id("leave_request"),time=now(),payload={personId:preview.person.id,employmentId:preview.person.employment_id,assignmentId:preview.assignment.id,policyVersionId:preview.assignment.policy_version_id,leaveTypeKey:input.leaveTypeKey,startsOn:input.startsOn,endsOn:input.endsOn,portion:input.portion,requestedMinutes:preview.requestedMinutes,days:preview.days,privateReason:input.privateReason.trim(),handoffNote:input.handoffNote.trim()},calculation=JSON.stringify({timezone:preview.assignment.timezone,policy_version_id:preview.assignment.policy_version_id,calendar_version_id:preview.assignment.calendar_version_id,days:preview.days,requested_minutes:preview.requestedMinutes});await command(db,user,key,"leave_request_submit",payload,requestId,[guard(db,"NOT EXISTS(SELECT 1 FROM hrm_time_periods WHERE state IN ('locked','reopen_requested') AND starts_on<=? AND ends_on>=?)",[input.endsOn,input.startsOn]),guard(db,"NOT EXISTS(SELECT 1 FROM hrm_leave_requests WHERE person_id=? AND starts_on<=? AND ends_on>=? AND state IN ('pending_approval','approved','cancellation_requested'))",[preview.person.id,input.endsOn,input.startsOn]),guard(db,"EXISTS(SELECT 1 FROM hrm_leave_policy_assignments WHERE id=? AND policy_version_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?))",[preview.assignment.id,preview.assignment.policy_version_id,input.startsOn,input.endsOn]),guard(db,"SELECT 1 WHERE ?=0 OR ((SELECT COALESCE(SUM(minutes),0) FROM hrm_leave_ledger WHERE employment_id=? AND leave_type_key=?)-(SELECT COALESCE(SUM(requested_minutes),0) FROM hrm_leave_requests WHERE employment_id=? AND leave_type_key=? AND state='pending_approval')) >= ?",[preview.rule.paid?1:0,preview.person.employment_id,input.leaveTypeKey,preview.person.employment_id,input.leaveTypeKey,preview.requestedMinutes-preview.rule.max_negative_minutes])],[db.prepare("INSERT INTO hrm_leave_requests(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,starts_on,ends_on,portion,requested_minutes,calculation_json,private_reason,handoff_note,state,submitted_by,submitted_at,version,actor_id,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'pending_approval',?,?,1,?,?,?)").bind(requestId,preview.person.id,preview.person.employment_id,preview.assignment.id,preview.assignment.policy_version_id,input.leaveTypeKey,input.startsOn,input.endsOn,input.portion,preview.requestedMinutes,calculation,input.privateReason.trim(),input.handoffNote.trim(),user.id,time,user.id,time,time),db.prepare("INSERT INTO hrm_leave_events(id,leave_request_id,action,actor_id,detail_json,created_at) VALUES(?,?, 'submitted',?,?,?)").bind(id("leave_event"),requestId,user.id,JSON.stringify({requested_minutes:preview.requestedMinutes}),time),db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'leave_request_submitted',?,?,?,?)").bind(user.id,preview.person.id,requestId,JSON.stringify({leave_type_key:input.leaveTypeKey,starts_on:input.startsOn,ends_on:input.endsOn,requested_minutes:preview.requestedMinutes}),time),db.prepare("DELETE FROM hrm_write_guards")]);return requestId}
export async function listLeaveRequests(db:D1Database,user:WorkspaceUser):Promise<LeaveRequest[]>{live(user);if(!user.can("hrm.leave.self")&&!user.can("hrm.leave.manage")&&!user.can("hrm.leave.review"))fail("forbidden",403);const hasManage=user.can("hrm.leave.manage"),hasReview=user.can("hrm.leave.review"),self=(await db.prepare("SELECT id FROM hrm_people WHERE user_id=? ORDER BY created_at DESC LIMIT 1").bind(user.id).first<{id:string}>())?.id??"";let where="",params:(string|number|null)[]=[];if(!hasManage){if(hasReview){where=" AND (r.person_id=? OR EXISTS(SELECT 1 FROM hrm_employments e WHERE e.id=r.employment_id AND e.manager_user_id=?))";params=[self,user.id]}else{where=" AND r.person_id=?";params=[self]}}const privateAllowed=hasManage?1:0;const sql=`SELECT r.*,p.employee_code,p.preferred_name,CASE WHEN p.user_id=? OR ?=1 THEN r.private_reason ELSE '' END AS private_reason,json_extract(j.value,'$.title_en') AS leave_title_en,json_extract(j.value,'$.title_vi') AS leave_title_vi,CASE WHEN json_extract(j.value,'$.paid')=1 THEN 1 ELSE 0 END AS paid FROM hrm_leave_requests r JOIN hrm_people p ON p.id=r.person_id JOIN hrm_leave_policy_versions v ON v.id=r.policy_version_id JOIN json_each(v.rules_json) j ON json_extract(j.value,'$.key')=r.leave_type_key WHERE 1=1${where} ORDER BY r.submitted_at DESC LIMIT 500`;const rows=(await db.prepare(sql).bind(user.id,privateAllowed,...params).all<LeaveRequest>()).results;return rows.map(row=>!hasManage&&row.person_id!==self?{...row,private_reason:"",cancellation_reason:null}:row)}

export async function reviewLeaveRequest(db:D1Database,user:WorkspaceUser,key:string,requestId:string,version:number,approve:boolean,reason:string):Promise<void>{requirePermission(user,"hrm.leave.review");live(user);if(!reason.trim())fail("reason_required",400);const request=await db.prepare("SELECT * FROM hrm_leave_requests WHERE id=?").bind(requestId).first<LeaveRequest>();if(!request)fail("not_found",404);await reviewerScope(db,user,request.person_id,"leave");if(request.submitted_by===user.id)fail("self_approval",403);if(request.state!=="pending_approval")fail("invalid_transition",409);const policy=await db.prepare("SELECT rules_json FROM hrm_leave_policy_versions WHERE id=?").bind(request.policy_version_id).first<{rules_json:string}>();if(!policy)fail("not_found",404);const rule=parseLeaveRules(policy.rules_json).find(row=>row.key===request.leave_type_key);if(!rule)fail("leave_type_unavailable",409);const time=now(),next=approve?"approved":"rejected",payload={requestId,version,approve,reason:reason.trim()},writes:D1PreparedStatement[]=[];if(approve&&rule.paid)writes.push(db.prepare("INSERT INTO hrm_leave_ledger(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,event_kind,minutes,period_key,reference_id,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,'used',?,?,?,?,?,?)").bind(id("leave_event"),request.person_id,request.employment_id,request.assignment_id,request.policy_version_id,request.leave_type_key,-request.requested_minutes,year(request.starts_on),request.id,reason.trim(),user.id,time));writes.push(db.prepare("UPDATE hrm_leave_requests SET state=?,reviewed_by=?,reviewed_at=?,review_reason=?,version=version+1,actor_id=?,updated_at=? WHERE id=? AND version=? AND state='pending_approval'").bind(next,user.id,time,reason.trim(),user.id,time,requestId,version),db.prepare("INSERT INTO hrm_leave_events(id,leave_request_id,action,actor_id,detail_json,created_at) VALUES(?,?,?,?,?,?)").bind(id("leave_event"),requestId,next,user.id,JSON.stringify({reason:reason.trim(),requested_minutes:request.requested_minutes}),time),db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,?,?,?,?,?)").bind(user.id,"leave_request_"+next,request.person_id,requestId,JSON.stringify({reason:reason.trim()}),time),db.prepare("DELETE FROM hrm_write_guards"));const guards=[guard(db,"EXISTS(SELECT 1 FROM hrm_leave_requests WHERE id=? AND version=? AND state='pending_approval' AND submitted_by!=?)",[requestId,version,user.id])];if(approve&&rule.paid)guards.push(guard(db,"SELECT 1 WHERE ((SELECT COALESCE(SUM(minutes),0) FROM hrm_leave_ledger WHERE employment_id=? AND leave_type_key=?)-(SELECT COALESCE(SUM(requested_minutes),0) FROM hrm_leave_requests WHERE employment_id=? AND leave_type_key=? AND state='pending_approval' AND id!=?)) >= ?",[request.employment_id,request.leave_type_key,request.employment_id,request.leave_type_key,requestId,request.requested_minutes-rule.max_negative_minutes]));await command(db,user,key,"leave_request_review",payload,requestId,guards,writes)}

export async function withdrawLeaveRequest(db:D1Database,user:WorkspaceUser,key:string,requestId:string,version:number):Promise<void>{live(user);const person=await ownPerson(db,user),request=await db.prepare("SELECT person_id,state FROM hrm_leave_requests WHERE id=?").bind(requestId).first<{person_id:string;state:string}>();if(!request||request.person_id!==person.id)fail("not_found",404);if(request.state!=="pending_approval")fail("invalid_transition",409);const time=now(),payload={requestId,version};await command(db,user,key,"leave_request_withdraw",payload,requestId,[guard(db,"EXISTS(SELECT 1 FROM hrm_leave_requests WHERE id=? AND person_id=? AND version=? AND state='pending_approval')",[requestId,person.id,version])],[db.prepare("UPDATE hrm_leave_requests SET state='withdrawn',version=version+1,actor_id=?,updated_at=? WHERE id=? AND version=? AND state='pending_approval'").bind(user.id,time,requestId,version),db.prepare("INSERT INTO hrm_leave_events(id,leave_request_id,action,actor_id,detail_json,created_at) VALUES(?,?, 'withdrawn',?,'{}',?)").bind(id("leave_event"),requestId,user.id,time),db.prepare("DELETE FROM hrm_write_guards")])}
export async function requestLeaveCancellation(db:D1Database,user:WorkspaceUser,key:string,requestId:string,version:number,reason:string):Promise<void>{live(user);if(!reason.trim())fail("reason_required",400);const person=await ownPerson(db,user),request=await db.prepare("SELECT person_id,state,starts_on,ends_on FROM hrm_leave_requests WHERE id=?").bind(requestId).first<{person_id:string;state:string;starts_on:string;ends_on:string}>();if(!request||request.person_id!==person.id)fail("not_found",404);if(request.state!=="approved")fail("invalid_transition",409);if(await db.prepare("SELECT 1 FROM hrm_time_periods WHERE state IN ('locked','reopen_requested') AND starts_on<=? AND ends_on>=? LIMIT 1").bind(request.ends_on,request.starts_on).first())fail("leave_cancel_requires_adjustment",409);const time=now(),payload={requestId,version,reason:reason.trim()};await command(db,user,key,"leave_cancel_request",payload,requestId,[guard(db,"EXISTS(SELECT 1 FROM hrm_leave_requests WHERE id=? AND person_id=? AND version=? AND state='approved')",[requestId,person.id,version]),guard(db,"NOT EXISTS(SELECT 1 FROM hrm_time_periods WHERE state IN ('locked','reopen_requested') AND starts_on<=? AND ends_on>=?)",[request.ends_on,request.starts_on])],[db.prepare("UPDATE hrm_leave_requests SET state='cancellation_requested',cancellation_reason=?,version=version+1,actor_id=?,updated_at=? WHERE id=? AND version=? AND state='approved'").bind(reason.trim(),user.id,time,requestId,version),db.prepare("INSERT INTO hrm_leave_events(id,leave_request_id,action,actor_id,detail_json,created_at) VALUES(?,?, 'cancellation_requested',?,?,?)").bind(id("leave_event"),requestId,user.id,JSON.stringify({reason:reason.trim()}),time),db.prepare("DELETE FROM hrm_write_guards")])}
export async function reviewLeaveCancellation(db:D1Database,user:WorkspaceUser,key:string,requestId:string,version:number,approve:boolean,reason:string):Promise<void>{requirePermission(user,"hrm.leave.review");live(user);if(!reason.trim())fail("reason_required",400);const request=await db.prepare("SELECT * FROM hrm_leave_requests WHERE id=?").bind(requestId).first<LeaveRequest>();if(!request)fail("not_found",404);await reviewerScope(db,user,request.person_id,"leave");if(request.submitted_by===user.id)fail("self_approval",403);if(request.state!=="cancellation_requested")fail("invalid_transition",409);if(approve&&await db.prepare("SELECT 1 FROM hrm_time_periods WHERE state IN ('locked','reopen_requested') AND starts_on<=? AND ends_on>=? LIMIT 1").bind(request.ends_on,request.starts_on).first())fail("leave_cancel_requires_adjustment",409);const policy=await db.prepare("SELECT rules_json FROM hrm_leave_policy_versions WHERE id=?").bind(request.policy_version_id).first<{rules_json:string}>();const rule=policy?parseLeaveRules(policy.rules_json).find(item=>item.key===request.leave_type_key):null;const time=now(),state=approve?"cancelled":"cancellation_rejected",payload={requestId,version,approve,reason:reason.trim()},writes:D1PreparedStatement[]=[];if(approve&&rule?.paid)writes.push(db.prepare("INSERT INTO hrm_leave_ledger(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,event_kind,minutes,period_key,reference_id,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,'returned',?,?,?,?,?,?)").bind(id("leave_event"),request.person_id,request.employment_id,request.assignment_id,request.policy_version_id,request.leave_type_key,request.requested_minutes,year(request.starts_on),request.id,reason.trim(),user.id,time));writes.push(db.prepare("UPDATE hrm_leave_requests SET state=?,reviewed_by=?,reviewed_at=?,review_reason=?,version=version+1,actor_id=?,updated_at=? WHERE id=? AND version=? AND state='cancellation_requested'").bind(state,user.id,time,reason.trim(),user.id,time,requestId,version),db.prepare("INSERT INTO hrm_leave_events(id,leave_request_id,action,actor_id,detail_json,created_at) VALUES(?,?,?,?,?,?)").bind(id("leave_event"),requestId,state,user.id,JSON.stringify({reason:reason.trim()}),time),db.prepare("DELETE FROM hrm_write_guards"));await command(db,user,key,"leave_cancel_review",payload,requestId,[guard(db,"EXISTS(SELECT 1 FROM hrm_leave_requests WHERE id=? AND version=? AND state='cancellation_requested' AND submitted_by!=?)",[requestId,version,user.id])],writes)}

export async function adjustLeaveBalance(db:D1Database,user:WorkspaceUser,key:string,input:{personId:string;typeKey:string;minutes:number;periodKey:string;reason:string}):Promise<string>{requirePermission(user,"hrm.leave.manage");live(user);if(!Number.isInteger(input.minutes)||input.minutes===0||Math.abs(input.minutes)>1000000||!/^\d{4}$/.test(input.periodKey)||!input.reason.trim())fail("invalid_request",400);const person=await personFor(db,user,input.personId),assignment=await db.prepare("SELECT a.*,p.rules_json FROM hrm_leave_policy_assignments a JOIN hrm_leave_policy_versions p ON p.id=a.policy_version_id WHERE a.person_id=? AND a.employment_id=? AND a.effective_from<=? AND (a.effective_to IS NULL OR a.effective_to>=?) ORDER BY a.effective_from DESC LIMIT 1").bind(person.id,person.employment_id,input.periodKey+"-12-31",input.periodKey+"-01-01").first<LeaveAssignment&{rules_json:string}>();if(!assignment)fail("leave_policy_assignment_missing",409);const rule=parseLeaveRules(assignment.rules_json).find(item=>item.key===input.typeKey);if(!rule)fail("leave_type_unavailable",409);const eventId=id("leave_adjustment"),time=now(),payload={personId:person.id,employmentId:person.employment_id,assignmentId:assignment.id,typeKey:rule.key,minutes:input.minutes,periodKey:input.periodKey,reason:input.reason.trim()};await command(db,user,key,"leave_balance_adjust",payload,eventId,[guard(db,"SELECT 1 WHERE ? >= 0 OR ((SELECT COALESCE(SUM(minutes),0) FROM hrm_leave_ledger WHERE employment_id=? AND leave_type_key=?)+?) >= ?",[input.minutes,person.employment_id,rule.key,input.minutes,-rule.max_negative_minutes])],[db.prepare("INSERT INTO hrm_leave_ledger(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,event_kind,minutes,period_key,reference_id,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,'manual_adjustment',?,?,?,?,?,?)").bind(eventId,person.id,person.employment_id,assignment.id,assignment.policy_version_id,rule.key,input.minutes,input.periodKey,eventId,input.reason.trim(),user.id,time),db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'leave_balance_adjusted',?,?,?,?)").bind(user.id,person.id,eventId,JSON.stringify({leave_type_key:rule.key,minutes:input.minutes,period_key:input.periodKey,reason:input.reason.trim()}),time),db.prepare("DELETE FROM hrm_write_guards")]);return eventId}

export async function runAnnualLeaveRollover(db:D1Database,user:WorkspaceUser,key:string,targetYear:string):Promise<number>{
 requirePermission(user,"hrm.leave.manage");live(user);
 if(!/^\d{4}$/.test(targetYear)||Number(targetYear)!==Number(year(localDate()))+1)fail("invalid_date",400);
 const effectiveOn=targetYear+"-01-01";
 const assignments=(await db.prepare("SELECT a.*,p.rules_json FROM hrm_leave_policy_assignments a JOIN hrm_leave_policy_versions p ON p.id=a.policy_version_id WHERE a.effective_from<=? AND (a.effective_to IS NULL OR a.effective_to>=?)").bind(effectiveOn,effectiveOn).all<LeaveAssignment&{rules_json:string}>()).results;
 const writes:D1PreparedStatement[]=[],time=now();let count=0;
 for(const assignment of assignments){
  for(const rule of parseLeaveRules(assignment.rules_json)){
   const prior=await db.prepare("SELECT COALESCE(SUM(minutes),0) AS n FROM hrm_leave_ledger WHERE employment_id=? AND leave_type_key=? AND period_key<?").bind(assignment.employment_id,rule.key,targetYear).first<{n:number}>();
   const balance=prior?.n??0;if(balance<=0)continue;
   const carry=Math.min(balance,rule.carryover_limit_minutes),expire=balance-carry,reference=assignment.id+":"+rule.key+":"+targetYear;
   if(carry>0&&!await db.prepare("SELECT 1 FROM hrm_leave_ledger WHERE reference_id=? AND event_kind='carryover'").bind(reference).first()){
    writes.push(db.prepare("INSERT INTO hrm_leave_ledger(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,event_kind,minutes,period_key,reference_id,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,'carryover',?,?,?,?,?,?)").bind(id("leave_event"),assignment.person_id,assignment.employment_id,assignment.id,assignment.policy_version_id,rule.key,carry,targetYear,reference,"Configured carryover limit.",user.id,time));count++;
   }
   if(expire>0&&!await db.prepare("SELECT 1 FROM hrm_leave_ledger WHERE reference_id=? AND event_kind='expired'").bind(reference).first()){
    writes.push(db.prepare("INSERT INTO hrm_leave_ledger(id,person_id,employment_id,assignment_id,policy_version_id,leave_type_key,event_kind,minutes,period_key,reference_id,reason,actor_id,created_at) VALUES(?,?,?,?,?,?,'expired',?,?,?,?,?,?)").bind(id("leave_event"),assignment.person_id,assignment.employment_id,assignment.id,assignment.policy_version_id,rule.key,-expire,targetYear,reference,"Configured annual rollover expiry.",user.id,time));count++;
   }
  }
 }
 if(!writes.length)return 0;
 await command(db,user,key,"leave_annual_rollover",{targetYear,assignmentIds:assignments.map(row=>row.id)},id("leave_rollover"),[guard(db,"EXISTS(SELECT 1 FROM hrm_settings WHERE id=1)",[])],[...writes,db.prepare("INSERT INTO hrm_audit(actor_id,action,person_id,target_id,detail,created_at) VALUES(?,'leave_annual_rollover',NULL,?,?,?)").bind(user.id,targetYear,JSON.stringify({assignment_count:assignments.length,entries:count}),time),db.prepare("DELETE FROM hrm_write_guards")]);
 return count;
}

export async function myTimeContext(db:D1Database,user:WorkspaceUser,workDate:string):Promise<{person:Person;assignment:WorkAssignment&{timezone:string;schedule_json:string};schedule:CalendarSchedule;periods:TimePeriod[]}>{requirePermission(user,"hrm.time.self");live(user);checkTimeRange(workDate);const person=await ownPerson(db,user),assignment=await activeAssignment(db,person,workDate),schedule=parseCalendarSchedule(assignment.schedule_json),periods=(await db.prepare("SELECT * FROM hrm_time_periods WHERE state IN ('open','reopened') AND starts_on<=? AND ends_on>=? ORDER BY starts_on DESC LIMIT 30").bind(workDate,workDate).all<TimePeriod>()).results;return {person,assignment,schedule,periods}}
export async function myLeaveOptions(db:D1Database,user:WorkspaceUser,date:string):Promise<{person:Person;assignment:LeaveAssignment&{rules_json:string;timezone:string;schedule_json:string;calendar_version_id:string};rules:LeaveRule[]}>{requirePermission(user,"hrm.leave.self");live(user);checkTimeRange(date);const person=await ownPerson(db,user),assignment=await leaveAssignment(db,person,date);return {person,assignment,rules:parseLeaveRules(assignment.rules_json)}}
export async function assignmentTimezone(db:D1Database,user:WorkspaceUser,personId:string,date:string):Promise<string>{checkTimeRange(date);const person=await personFor(db,user,personId);if(!own(person,user)&&!user.can("hrm.time.manage"))fail("not_found",404);return (await activeAssignment(db,person,date)).timezone}
export function localDateTimeToUtc(value:string,timezone:string):string{if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(value)||!timezoneValid(timezone))fail("invalid_time",400);const [date,time]=value.split("T"),[y,m,d]=date.split("-").map(Number),[h,min]=time.split(":").map(Number);if(!validDate(date)||h>23||min>59)fail("invalid_time",400);const target=Date.UTC(y,m-1,d,h,min),formatter=new Intl.DateTimeFormat("en-CA",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}),matches:number[]=[];for(let offset=-840;offset<=840;offset+=15){const candidate=target+offset*60000,parts=Object.fromEntries(formatter.formatToParts(new Date(candidate)).map(part=>[part.type,part.value]));if(Number(parts.year)===y&&Number(parts.month)===m&&Number(parts.day)===d&&Number(parts.hour)===h&&Number(parts.minute)===min)matches.push(candidate)}if(matches.length!==1)fail("invalid_time",400);return new Date(matches[0]).toISOString()}
